export interface UserRating {
  /**
   * Numeric value for a numeric system, NULL for a graded system (BR-ACC-11).
   */
  numeric_value: Numeric | null;
  /**
   * Grade for a graded system, NULL for a numeric system (BR-ACC-11).
   */
  rating_grade_id: string | null;
  /**
   * Rating system of the value.
   */
  rating_system_id: string;
  /**
   * Last update instant (maintained by trigger).
   */
  updated_at: Generated<Timestamp>;
  /**
   * Rated account.
   */
  user_id: string;
}

export interface UserSetting {
  /**
   * Who can see the badges section (BR-ACC-14).
   */
  badges_visibility: Generated<VisibilityLevel>;
  /**
   * Who can invite the user to circles (BR-ACC-15).
   */
  circle_invite_policy: Generated<InvitePolicy>;
  /**
   * Who can see the circles section (BR-ACC-14).
   */
  circles_visibility: Generated<VisibilityLevel>;
  /**
   * Who can see the follows section (BR-ACC-14).
   */
  follows_visibility: Generated<VisibilityLevel>;
  /**
   * When true, the user is left out of city rankings (BR-ACC-15).
   */
  hide_from_rankings: Generated<boolean>;
  /**
   * Who can see the event history section (BR-ACC-14).
   */
  history_visibility: Generated<VisibilityLevel>;
  /**
   * When true, follow requests need approval (BR-ACC-14).
   */
  is_private_account: Generated<boolean>;
  /**
   * Who can see the profile section (BR-ACC-14).
   */
  profile_visibility: Generated<VisibilityLevel>;
  /**
   * Who can see the reliability section (BR-ACC-14).
   */
  reliability_visibility: Generated<VisibilityLevel>;
  /**
   * Who can see the statistics section (BR-ACC-14).
   */
  stats_visibility: Generated<VisibilityLevel>;
  /**
   * Last update instant (maintained by trigger).
   */
  updated_at: Generated<Timestamp>;
  /**
   * Owner account, also the primary key (one settings row per account).
   */
  user_id: string;
}

export interface UserSport {
  /**
   * Instant the sport was declared.
   */
  created_at: Generated<Timestamp>;
  /**
   * Self-declared level on the shared scale (BR-ACC-10).
   */
  skill_level_id: string;
  /**
   * Declared sport.
   */
  sport_id: string;
  /**
   * Declaring account.
   */
  user_id: string;
}

export interface Venue {
  /**
   * Text address of the venue (BR-EVT-08).
   */
  address: string;
  /**
   * When the venue was created.
   */
  created_at: Generated<Timestamp>;
  /**
   * Creator of the venue; NULL after erasure of the creator (BR-GDP-04).
   */
  created_by_id: string | null;
  /**
   * Primary key, UUID v7.
   */
  id: Generated<string>;
  /**
   * When true, only the creator sees the venue in searches (BR-EVT-08).
   */
  is_private: Generated<boolean>;
  /**
   * GPS point of the venue (WGS 84 geography, BR-EVT-08).
   */
  location: string;
  /**
   * Municipality or arrondissement of the venue (BR-ACC-19).
   */
  municipality_id: string;
  /**
   * Name of the venue, searchable with trigram matching (BR-TECH-10).
   */
  name: string;
}

export interface DB {
  account_token: AccountToken;
  attendance_dispute: AttendanceDispute;
  auth_identity: AuthIdentity;
  circle: Circle;
  circle_invitation: CircleInvitation;
  circle_member: CircleMember;
  community: Community;
  community_join_request: CommunityJoinRequest;
  community_member: CommunityMember;
  event: Event;
  event_circle: EventCircle;
  event_co_organizer: EventCoOrganizer;
  event_occurrence: EventOccurrence;
  follow: Follow;
  municipality: Municipality;
  rating_grade: RatingGrade;
  rating_system: RatingSystem;
  refresh_token: RefreshToken;
  registration: Registration;
  registration_guest: RegistrationGuest;
  skill_level: SkillLevel;
  sport: Sport;
  user_account: UserAccount;
  user_availability: UserAvailability;
  user_block: UserBlock;
  user_rating: UserRating;
  user_setting: UserSetting;
  user_sport: UserSport;
  venue: Venue;
}
